import { pickBy } from 'lodash-es';
import { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';
import { CustomRenderFn } from './types';
import { h, VNode } from '@stencil/core';

/** Default filter function for dropdown menu search. */
export const defaultFilter = (searchQuery: string, option: DropdownItem) =>
  String(option.label).toLowerCase().includes(searchQuery.toLowerCase());

/** Filter data attributes from the given attributes. */
export const filterDataAttrs = (attrs: Record<string, string | boolean>): Record<`data-${string}`, string | boolean> =>
  pickBy(attrs, (_, key) => key.startsWith('data-'));

/** Get the slot name for a dropdown menu tab. */
export const getTabSlotNameFromSlotType = (slotType: string, tabId?: string) =>
  `slot-tab-${tabId || 'INVALID'}-${slotType}`;

/**
 * Render the slots for a dropdown menu tab.
 * Note: This only render tabs related slots. If you want to render item related slots, please also use `internalRenderDynamicSlotsForItems`.
 */
export const internalRenderDynamicSlotsForTabs = (
  props: {
    tabId: string;
    label?: string | CustomRenderFn;
    helpContent?: string | CustomRenderFn;
  },
  wrapWithSlot: (slotName: string, children: unknown) => unknown,
) => {
  const dynamicSlots: Array<unknown> = [];
  if (props.label) {
    dynamicSlots.push(
      wrapWithSlot(
        getTabSlotNameFromSlotType('label', props.tabId),
        typeof props.label === 'function' ? props.label() : props.label,
      ),
    );
  }
  if (props.helpContent && typeof props.helpContent === 'function') {
    dynamicSlots.push(wrapWithSlot(getTabSlotNameFromSlotType('helpContent', props.tabId), props.helpContent()));
  }
  return dynamicSlots;
};

export const internalRenderPassThroughSlotsForTabs = (props: {
  tabId: string;
  label?: string | CustomRenderFn;
  helpContent?: string | CustomRenderFn;
}) => {
  const passThroughSlots: Array<VNode> = [];
  if (props.label) {
    passThroughSlots.push(
      h('slot', {
        name: getTabSlotNameFromSlotType('label', props.tabId),
        slot: getTabSlotNameFromSlotType('label', props.tabId),
        key: getTabSlotNameFromSlotType('label', props.tabId),
      }),
    );
  }
  if (props.helpContent && typeof props.helpContent === 'function') {
    passThroughSlots.push(
      h('slot', {
        name: getTabSlotNameFromSlotType('helpContent', props.tabId),
        slot: getTabSlotNameFromSlotType('helpContent', props.tabId),
        key: getTabSlotNameFromSlotType('helpContent', props.tabId),
      }),
    );
  }
  return passThroughSlots;
};
