/* eslint-disable max-lines */
import {
  Component,
  Host,
  h,
  Prop,
  Event,
  EventEmitter,
  State,
  Element,
  Watch,
  ComponentInterface,
  Listen,
  VNode,
  Fragment,
} from '@stencil/core';
import { CustomRenderFn, DropdownMenuPartProps, DropdownPopoverProps, DropdownSearchConfig } from './types';
import { Value } from '@src/components/ks-value-field/types';
import type { Placement } from '@floating-ui/dom';
import { Slot, Slots, Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { searchMessages } from '@fe-infra/keystone-locales';
import {
  defaultFilter,
  getTabSlotNameFromSlotType,
  internalRenderDynamicSlotsForTabs,
  internalRenderPassThroughSlotsForTabs,
} from './utils';
import { noop } from 'lodash-es';
import { DetailArgs } from '@src/shared/dom';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { t } from '@src/shared/i18n';
import { DropdownItem } from '@src/components/ks-dropdown-menu-list/types';
import { KsTooltip } from '@src/components/ks-tooltip';
import { getPartProps } from '@src/shared/base-props';
import { convertDataToEntities, DataEntity, FlattenNode } from '@src/components/ks-tree-view/utils';
import { asObject } from '@src/shared/type-utils';
import { KsIconHelp, KsIconSearch } from '@fe-infra/keystone-icons-stencil';

const prefix = 'dropdown-menu';

/**
 * dropdown
 * @slot default - Trigger content that anchors the dropdown menu popover.
 * @slot popupFooter - Slot for custom footer for the dropdown menu.
 *
 * dropdown menu list
 * @slot listHeader - Slot for custom header at the top of the list (scrollable area in DropdownMenu).
 * @slot empty - Slot for custom content when the list is empty.
 * @slot loadFailure - Slot for custom content when the list fails to load.
 * @slot loadMoreFailure - Slot for custom content when the list fails to load more items.
 * @part popup - The popup container.
 * @part innerPopupContent - The inner popup content area exported from the nested `ks-dropdown-menu-list`.
 */
@Component({
  tag: 'ks-dropdown-menu',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsDropdownMenu implements ComponentInterface {
  protected static vModel = { prop: 'value', event: 'ksChange' };

  @Element() el!: HTMLKsDropdownMenuElement;
  private inputRef?: HTMLKsInputElement;

  // ====== Options ======
  /** The options of the dropdown menu. Please Note: If tabOptions is passed, options will be ignored. */
  @Prop() options?: DropdownItem[];
  /** The options of the dropdown menu tabs. */
  @Prop() tabOptions?: {
    tabId: string;
    label?: string | CustomRenderFn;
    helpContent?: string | CustomRenderFn;
    options?: DropdownItem[];
  }[];
  private mode: 'list' | 'tabs' = 'list';
  public keyEntities: Record<Value, DataEntity<DropdownItem>> = {};
  private key2TabIdMap: Record<Value, string[]> = {};
  @Watch('options')
  @Watch('tabOptions')
  private handleOptionsChange() {
    const currentValues = this.getCurrentValues();
    if (this.options) {
      this.mode = 'list';
      const entitiesMap = convertDataToEntities(this.options);
      this.keyEntities = entitiesMap.keyEntities;
    } else if (this.tabOptions) {
      this.mode = 'tabs';
      this.key2TabIdMap = {};
      const setTabIdMap = (value: Value, tabId: string) => {
        const tabIds = this.key2TabIdMap[value] || [];
        if (!tabIds.includes(tabId)) {
          this.key2TabIdMap[value] = [...tabIds, tabId];
        }
      };
      const processOptions = (options: DropdownItem[] | undefined, tabId: string) => {
        options?.forEach((option) => {
          setTabIdMap(option.value, tabId);
          processOptions(option.children, tabId);
        });
      };
      this.tabOptions.forEach((item) => {
        processOptions(item.options, item.tabId);
      });
      const entitiesMap = convertDataToEntities(this.tabOptions.flatMap((item) => item.options || []));
      this.keyEntities = entitiesMap.keyEntities;

      this.tabsDynamicChildren = this.tabOptions.flatMap<unknown>((item) =>
        internalRenderDynamicSlotsForTabs(item, this.wrapWithSlot),
      );
      this.getPassThroughSlotsForTabs = () =>
        this.tabOptions?.flatMap((item) => internalRenderPassThroughSlotsForTabs(item)) || [];

      if (!this.internalActiveTabIdState) {
        this.internalActiveTabIdState = this.tabOptions[0]?.tabId;
      }
    }
    if (currentValues !== undefined) {
      this.internalValueState = this.getValueStateFromValues(currentValues);
    }
    this.optionsChange?.emit();
  }
  private getPassThroughSlotsForTabs?: () => VNode[];
  private tabsDynamicChildren: unknown[] = [];

  // ====== Value ======
  /** An array of IDs representing the currently active items in the dropdown menu. */
  @Prop() @Vue2ValueFix() value?: Value[];
  /** The default value of the dropdown menu. */
  @Prop() defaultValue?: Value[];

  // list mode: Value[]
  // tabs mode: Record<tabId, Value[]>
  @State() internalValueState?: Value[] | Record<string, Value[]>;
  private getCurrentValues() {
    const mergedValue = this.value || this.defaultValue;
    if (Array.isArray(mergedValue)) {
      return mergedValue;
    }
    return Array.isArray(this.internalValueState)
      ? this.internalValueState
      : Array.from(new Set(Object.values<Value[]>((this.internalValueState || {}) as Record<string, Value[]>).flat()));
  }
  private getValueStateFromValues(values: Value[]) {
    if (this.mode === 'list') {
      return values;
    }
    return values.reduce<Record<string, Value[]>>((acc, item) => {
      const tabIds = this.key2TabIdMap[item] || [];
      tabIds.forEach((tabId) => {
        acc[tabId] = [...(acc[tabId] || []), item];
      });
      return acc;
    }, {});
  }
  @Watch('value')
  handleValueChange() {
    const mergedValue = this.value || this.defaultValue;
    if (Array.isArray(mergedValue)) {
      this.internalValueState = this.getValueStateFromValues(mergedValue);
    }
  }
  private triggerChange(nextValues: Value[], tabId?: string) {
    switch (this.mode) {
      case 'list':
        {
          if (this.value === undefined && this.selectable) {
            this.internalValueState = nextValues;
          }
          const emitOptions: DropdownItem[] = [];
          nextValues.forEach((item) => {
            const entity = this.keyEntities[item];
            if (entity) {
              emitOptions.push(entity.node);
            }
          });
          this.ksChange.emit(DetailArgs(nextValues, emitOptions));
        }
        break;
      case 'tabs':
        {
          const currentState = (this.internalValueState || {}) as Record<string, Value[]>;
          const prevValues = currentState[tabId!] || [];
          const changedValues = [
            ...prevValues.filter((item) => !nextValues.includes(item)),
            ...nextValues.filter((item) => !prevValues.includes(item)),
          ];
          const nextState = {
            ...currentState,
            [tabId!]: nextValues,
          };
          changedValues.forEach((item) => {
            const tabIds = this.key2TabIdMap[item] || [];
            tabIds.forEach((relatedTabId) => {
              const relatedValues = nextState[relatedTabId] || [];
              nextState[relatedTabId] = nextValues.includes(item)
                ? relatedValues.includes(item)
                  ? relatedValues
                  : [...relatedValues, item]
                : relatedValues.filter((value) => value !== item);
            });
          });
          if (this.value === undefined && this.selectable) {
            this.internalValueState = nextState;
          }
          const nextTabsValues = Array.from(new Set(Object.values<Value[]>(nextState).flat()));
          const emitOptions: DropdownItem[] = [];
          nextTabsValues.forEach((item) => {
            const entity = this.keyEntities[item];
            if (entity) {
              emitOptions.push(entity.node);
            }
          });
          this.ksChange.emit(DetailArgs(nextTabsValues, emitOptions));
        }
        break;
      default:
        throw new Error('KsDropdownMenu: invalid mode');
    }

    if (!(this.multiple && this.selectable)) {
      const entity = this.keyEntities[nextValues[0]!];
      if (!entity?.node.hasPopup) {
        this.internalOpenState = false;
      }
    }
    if (this.search && typeof this.search === 'object' && this.search.autoClearSearchValue) {
      this.internalSearchValueState = '';
    }
  }

  // ====== tabs ======
  /** The ID of the currently active tab in the dropdown menu. This property is effective only when the `menu.type` is `tabs`. */
  @Prop() activeTabId?: string;
  /** The default ID of the currently active tab in the dropdown menu. This property is effective only when the `menu.type` is `tabs`. */
  @Prop() defaultActiveTabId = '';
  @Uncontrollable('activeTabId', 'defaultActiveTabId', 'ksActiveTabChange') @State() internalActiveTabIdState?: string;

  /** Controls whether the dropdown menu list supports multiple selection. When true, the dropdown menu list allows multiple selections. */
  @Prop() multiple?: boolean;

  /** Indicates whether the dropdown menu list is selectable. */
  @Prop() selectable = true;

  /**
   * The placement of the dropdown menu. Can be one of the following values:
   * `top`, `right`, `bottom`, `left`, `top-start`, `top-end`,
   * `right-start`, `right-end`, `bottom-start`, `bottom-end`,
   * `left-start`, and `left-end`.
   */
  @Prop() placement: Placement = 'bottom-start';

  /** Indicates whether the dropdown menu is currently open. */
  @Prop() open?: boolean;
  /** Indicates whether the dropdown menu is default open. */
  @Prop() defaultOpen?: boolean;
  @Uncontrollable('open', 'defaultOpen', 'ksOpenChange') @State() internalOpenState?: boolean;

  @State() private hasEverOpened = false;
  @Watch('internalOpenState')
  watchHasEverOpened(value?: boolean) {
    if (value && !this.hasEverOpened) {
      this.hasEverOpened = true;
    }
  }

  /** Popover props. */
  @Prop() popoverProps?: DropdownPopoverProps;

  /** The list has a default height, available for `popupHeight` to override. If `"auto"` is passed, the height will be auto-scaled. */
  @Prop() popupHeight: KsTooltip['popupHeight'] = { max: 381 };

  /** The width of the dropdown menu. */
  @Prop() popupWidth?: KsTooltip['popupWidth'] = { min: 120, value: 'matchAnchor' };

  /** Search config for the dropdown menu. In most scenarios, you can pass `true` to enable search. For custom scenarios, you can pass a config object to customize the search behavior. */
  @Prop() search?: boolean | DropdownSearchConfig;
  /** The current value of the search input in the dropdown menu. */
  @Prop() searchValue?: string;
  @State() _defaultSearchValue?: string;
  @Uncontrollable('searchValue', '_defaultSearchValue', 'ksSearch') @State() internalSearchValueState?: string;

  /** Controls whether dropdown menu is disabled. When true, the Dropdown card is not visible. */
  @Prop() disabled?: boolean;

  /** Whether the dropdown menu is loading. */
  @Prop() loading?: boolean;

  /** Whether the dropdown menu is loading more. */
  @Prop() loadingMore?: boolean;

  /** Indicates whether the dropdown menu list failed to load. */
  @Prop() loadFailed?: boolean;

  /** Indicates whether the dropdown menu list failed to load more items. */
  @Prop() loadMoreFailed?: boolean;

  /** Whether to hide the divider between groups of items. */
  @Prop() hideGroupDivider = false;

  /**
   * @private
   * @deprecated
   * Whether to hide the title of the search result.
   */
  @Prop() hideSearchResultTitle = false;

  /** Elements that should not trigger an out-click event.These elements are excluded from the out-click detection. */
  @Prop() closeOnClickOutside?: { ignoreEls: HTMLElement[] };

  /** Whether to enable virtualization. */
  @Prop() virtual?: boolean | { estimatedItemHeight: number | ((item: FlattenNode<DropdownItem>) => number) };

  /** Custom props for Dropdown parts. */
  @Prop() partProps?: DropdownMenuPartProps;

  /**
   * @private */
  @Event() optionsChange?: EventEmitter<void>;

  /** Custom event triggered when the value changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<DetailArgs<[Value[], DropdownItem[]]>>;
  @Listen('ksChange')
  onKsChange({ detail: [value, _] }: CustomEvent<DetailArgs<[Value[], DropdownItem[]]>>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'items',
      componentParams: { value },
    });
  }

  /** Custom event triggered when the search input value changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksSearch!: EventEmitter<string>;
  @Listen('ksSearch')
  onKsSearch({ detail: searchValue }: CustomEvent<string>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'search',
      componentParams: { searchValue },
    });
  }

  /** Custom event triggered when the open state of the dropdown menu changes. */
  @Event({ bubbles: false, composed: false }) ksOpenChange!: EventEmitter<boolean>;
  @Listen('ksOpenChange')
  onKsOpenChange({ detail: open }: CustomEvent<boolean>) {
    if (open) {
      sendExposeTracking(this.el, { eventType: 'popup' });
      sendDurationTracking(this.el, { eventType: 'popup', reset: true });
    } else {
      sendDurationTracking(this.el, { eventType: 'popup' });
    }
  }

  /** Custom event triggered when the active tab changes in the dropdown menu. */
  @Event({ bubbles: false, composed: false }) ksActiveTabChange!: EventEmitter<string>;
  @Listen('ksActiveTabChange')
  onKsActiveTabChange({ detail: tabId }: CustomEvent<string>) {
    sendActionTracking(this.el, {
      eventType: 'change',
      subEventType: 'tabs',
      componentParams: { tabId },
    });
  }

  /** Custom event triggered when the dropdown menu list hits the bottom. */
  @Event({ bubbles: false, composed: false }) ksHitBottom!: EventEmitter<HTMLDivElement>;

  /** The element that the DropdownMenu popup is anchored to. Clicking this element will trigger the opening and closing of the DropdownMenu. */
  // @Slot({ slotname: '_default' }) private defaultSlot?: Slots;

  /** Custom footer for the dropdown menu. */
  @Slot({ slotname: 'popupFooter' }) private popupFooterSlot?: Slots;

  /** The slot at the top of the list (scrollable area in DropdownMenu). */
  @Slot({ slotname: 'listHeader' }) private listHeaderSlots?: Slots;

  /** The slot to be displayed when the list is empty. */
  @Slot({ slotname: 'empty' }) private emptySlot?: Slots;

  /** The slot to be displayed when the list fails to load. */
  @Slot({ slotname: 'loadFailure' }) private loadFailureSlot?: Slots;

  /** The slot to be displayed when the list fails to load more items. */
  @Slot({ slotname: 'loadMoreFailure' }) private loadMoreFailureSlot?: Slots;

  /** whether there is a search input in the dropdown panel. */
  get showSearchInput() {
    return this.search === true || (typeof this.search === 'object' && !this.search.hideSearchInput);
  }

  private filterOption?: (option: DropdownItem) => boolean;
  private sortOption?: (option: DropdownItem, otherOption: DropdownItem) => number;
  @Watch('search')
  @Watch('internalSearchValueState')
  onInternalSearchValueStateChange() {
    const { filter = defaultFilter, sort = undefined } = typeof this.search === 'object' ? this.search : {};

    const filterOption = (option: DropdownItem) => filter(this.internalSearchValueState || '', option);
    this.filterOption = filterOption;
    this.sortOption = sort;
  }

  /** this is for logics of showing the search icon. */
  @State() private searchInputFocused = false;

  constructor() {
    registerPluginManager(this.el);
  }

  private renderTabsMenu(hideSearchResultTitle: boolean) {
    return (
      <ks-tabs
        class={`${prefix}__tabs`}
        type="lite"
        activeTabId={this.internalActiveTabIdState || this.tabOptions?.[0]?.tabId}
        onKsActiveTabIdChange={({ detail: tabId }) => {
          this.internalActiveTabIdState = tabId;
        }}
        data-testid="ks-dropdown-menu-index-oCeDzW"
      >
        {this.tabOptions?.map((tabOption) => {
          const { tabId, helpContent, options } = tabOption;
          return (
            <ks-tab-item key={tabId} tabId={tabId} class={`${prefix}__tabs__item`}>
              <div class={`${prefix}__tabs__item--header`} slot="header">
                <slot name={getTabSlotNameFromSlotType('label', tabId)} />
                {helpContent && (
                  <ks-tooltip size="md">
                    <KsIconHelp />
                    {typeof helpContent === 'function' ? (
                      <slot name={getTabSlotNameFromSlotType('helpContent', tabId)} slot="content" />
                    ) : (
                      <ks-text slot="content" variant="labelSm" richTextString={helpContent} />
                    )}
                  </ks-tooltip>
                )}
              </div>
              {this.internalActiveTabIdState === tabId && (
                <ks-dropdown-menu-list
                  options={options}
                  filterOption={this.filterOption}
                  sortOption={this.sortOption}
                  virtual={this.virtual}
                  loading={this.loading}
                  loadingMore={this.loadingMore}
                  loadFailed={this.loadFailed}
                  loadMoreFailed={this.loadMoreFailed}
                  selectable={this.selectable}
                  multiple={this.multiple}
                  disabled={this.disabled}
                  value={((this.internalValueState || {}) as Record<string, Value[]>)[tabId]}
                  searchValue={this.internalSearchValueState}
                  hideGroupDivider={this.hideGroupDivider}
                  hideSearchResultTitle={hideSearchResultTitle}
                  onKsChange={(event) => this.triggerChange(event.detail[0], tabId)}
                  onKsHitBottom={(event) => this.ksHitBottom.emit(event.detail)}
                  wrapWithSlot={this.wrapWithSlot}
                  setDynamicRenderDeps={(children, getPassThroughSlots) => {
                    this.setDynamicRenderDeps([...this.tabsDynamicChildren, ...children], () => [
                      ...(this.getPassThroughSlotsForTabs?.() || []),
                      ...(getPassThroughSlots?.() || []),
                    ]);
                    this.passThroughSlots = getPassThroughSlots?.() || [];
                  }}
                >
                  {this.listHeaderSlots && <slot name="listHeader" slot="listHeader" />}
                  {this.emptySlot && <slot name="empty" slot="empty" />}
                  {this.loadFailureSlot && <slot name="loadFailure" slot="loadFailure" />}
                  {this.loadMoreFailureSlot && <slot name="loadMoreFailure" slot="loadMoreFailure" />}
                  {this.passThroughSlots}
                </ks-dropdown-menu-list>
              )}
            </ks-tab-item>
          );
        })}
      </ks-tabs>
    );
  }

  render() {
    const searchPlaceholder = asObject(this.search)?.placeholder || t(searchMessages.placeholder);
    const hideSearchResultTitle = asObject(this.search)?.hideSearchResultTitle || this.hideSearchResultTitle || false;

    return (
      <Host class="KsDropdownMenu">
        <ks-popover
          size="auto"
          class={`${prefix}__tooltip`}
          trigger={this.popoverProps?.trigger || 'click'}
          placement={this.placement}
          disabled={this.disabled}
          open={this.internalOpenState}
          delay={this.popoverProps?.delay}
          gapOffset={this.popoverProps?.gapOffset}
          startOffset={this.popoverProps?.startOffset}
          arrow={false}
          onKsAfterOpen={() => {
            this.inputRef?.focusInput();
          }}
          closeOnClickOutside={
            this.multiple
              ? { ignoreEls: [this.el, ...(this.closeOnClickOutside?.ignoreEls || [])] }
              : this.closeOnClickOutside
          }
          onKsOpenChange={({ detail: open }) => {
            if (!this.disabled || !open) {
              this.internalOpenState = open;
            }
          }}
          popupHeight={this.popupHeight}
          popupWidth={this.popupWidth}
          data-testid="ks-dropdown-menu-index-b5ti6q"
          {...getPartProps(this, 'tooltip')}
        >
          <div class={`${prefix}__popup`} slot="content" part="popup" {...getPartProps(this, 'popup')}>
            <div class={`${prefix}__body`}>
              {this.showSearchInput ? (
                <ks-input
                  ref={(el) => (this.inputRef = el)}
                  onFocus={() => {
                    this.searchInputFocused = true;
                  }}
                  onBlur={() => {
                    this.searchInputFocused = false;
                  }}
                  clearable={true}
                  class={`${prefix}__search`}
                  value={this.internalSearchValueState}
                  placeholder={searchPlaceholder}
                  onKsChange={({ detail: searchValue }) => {
                    this.internalSearchValueState = searchValue;
                  }}
                  data-testid="ks-dropdown-menu-index-aaM2bd"
                >
                  {!this.searchInputFocused && !this.internalSearchValueState && <KsIconSearch slot="prefix" />}
                </ks-input>
              ) : null}
              <div class={`${prefix}__body-content`}>
                {this.hasEverOpened &&
                  (this.mode === 'tabs' ? (
                    this.renderTabsMenu(hideSearchResultTitle)
                  ) : (
                    <ks-dropdown-menu-list
                      exportparts="popupContent: innerPopupContent"
                      options={this.options}
                      filterOption={this.filterOption}
                      sortOption={this.sortOption}
                      virtual={this.virtual}
                      loading={this.loading}
                      loadingMore={this.loadingMore}
                      loadFailed={this.loadFailed}
                      loadMoreFailed={this.loadMoreFailed}
                      selectable={this.selectable}
                      multiple={this.multiple}
                      disabled={this.disabled}
                      value={this.internalValueState as Value[]}
                      searchValue={this.internalSearchValueState}
                      hideGroupDivider={this.hideGroupDivider}
                      hideSearchResultTitle={hideSearchResultTitle}
                      onKsChange={(event) => this.triggerChange(event.detail[0])}
                      onKsHitBottom={(event) => this.ksHitBottom.emit(event.detail)}
                      wrapWithSlot={this.wrapWithSlot}
                      setDynamicRenderDeps={(children, getPassThroughSlots) => {
                        this.setDynamicRenderDeps(children, getPassThroughSlots);
                        this.passThroughSlots = getPassThroughSlots?.() || [];
                      }}
                    >
                      {this.listHeaderSlots && <slot name="listHeader" slot="listHeader" />}
                      {this.emptySlot && <slot name="empty" slot="empty" />}
                      {this.loadFailureSlot && <slot name="loadFailure" slot="loadFailure" />}
                      {this.loadMoreFailureSlot && <slot name="loadMoreFailure" slot="loadMoreFailure" />}
                      {this.passThroughSlots}
                    </ks-dropdown-menu-list>
                  ))}
              </div>
            </div>
            {this.popupFooterSlot && (
              <Fragment>
                <ks-divider />
                <div class={`${prefix}__footer`}>
                  <slot name="popupFooter" />
                </div>
              </Fragment>
            )}
          </div>
          <slot />
        </ks-popover>
      </Host>
    );
  }

  componentWillLoad(): Promise<void> | void {
    this.handleOptionsChange();
    this.handleValueChange();
    if (this.internalOpenState) {
      this.hasEverOpened = true;
    }
  }

  @State() private passThroughSlots: VNode[] = [];
  /**
   * @private */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private */
  @Prop() setDynamicRenderDeps: (children: unknown[], getPassThroughSlots?: () => VNode[]) => void = noop;
}
